<script setup lang="ts">
import { computed } from 'vue';
import { controllerOemDisplayCatalog } from '@/bridge/controllerOemPresentation';
import { CONTROLLER_BUTTONS, CONTROLLER_SHORTCUT_MAX_INPUTS, formatControllerShortcutInputs, isHandheldExtendedKey, type ControllerShortcutInput, type ControllerShortcutRecordMode, type OemKeysSnapshot } from '@/bridge/controllerShortcutRules';
import { CONTROLLER_DIAGRAMS, controllerDiagramPersona } from '@/bridge/controllerDeviceDiagram';
const props = defineProps<{ method?: 'record' | 'oem'; variant?: 'quick' | 'confirm' | 'picker'; mode?: ControllerShortcutRecordMode; persona: string; inputs: readonly ControllerShortcutInput[]; captured: readonly ControllerShortcutInput[]; candidate?: readonly ControllerShortcutInput[] | null; catalog: OemKeysSnapshot; recording: boolean; busy: boolean; recordingBusy: boolean; status: string }>();
const emit = defineEmits<{ (event: 'method', value: 'record' | 'oem'): void; (event: 'oem-key', value: string): void; (event: 'confirm-oem'): void; (event: 'cancel-oem'): void; (event: 'record'): void; (event: 'cancel-recording'): void; (event: 'clear'): void }>();
const visibleInputs = computed(() => props.recording ? props.captured : props.method === 'oem' && props.candidate ? props.candidate : props.inputs);
const displayCatalog = computed(() => controllerOemDisplayCatalog(props.persona, props.catalog));
const dedicatedKeys = computed(() => displayCatalog.value.keys.filter(key => key.backIndex === null));
const rearKeys = computed(() => displayCatalog.value.keys.filter(key => key.backIndex !== null));
const selected = (code: string) => visibleInputs.value.some(input => input.source === 'oem' && input.code === code);
const manual = computed(() => props.method === 'oem');

function label(input: ControllerShortcutInput): string {
 if (input.source === 'controller') { const b=CONTROLLER_BUTTONS.find(b=>b.value===input.code),c=CONTROLLER_DIAGRAMS[controllerDiagramPersona(props.persona)].controls.find(c=>c.buttonIndex===b?.gamepadIndex);return input.code==='leftThumb'?'L3':input.code==='rightThumb'?'R3':c?.label.split(' / ')[0]||b?.label||input.code; }
 if (input.source === 'oem') return displayCatalog.value.keys.find(k=>k.keyId===input.code)?.label || input.code;
 return isHandheldExtendedKey(input)?`掌机 ${input.code}`:formatControllerShortcutInputs([input]);
}
const traditionalKeys=computed(()=>visibleInputs.value.filter(i=>(i.source==='keyboard'||i.source==='mouse')&&!isHandheldExtendedKey(i)));
const mixed=computed(()=>traditionalKeys.value.length>0&&visibleInputs.value.some(i=>i.source==='controller'||i.source==='oem'||isHandheldExtendedKey(i)));
</script>
<template>
 <section class="combo-input-editor" data-input-flow="record" :data-input-method="manual?'oem':'record'" :data-recording="recording" data-record-control>
  <div class="combo-section-head"><div class="input-methods" role="group" aria-label="输入方式"><button type="button" :aria-pressed="!manual" :disabled="busy||recordingBusy" @click="emit('method','record')">录制输入</button><button type="button" :aria-pressed="manual" :disabled="busy||recordingBusy" @click="emit('method','oem')">专用键 / 背键</button></div><span>最多 {{ CONTROLLER_SHORTCUT_MAX_INPUTS }} 键</span></div>
  <div class="combo-current" :class="{capturing:recording}" aria-live="polite"><span class="combo-current-caption">{{recording?'正在识别':'当前组合'}}</span><div class="combo-chips"><template v-for="(input,index) in visibleInputs" :key="input.source+':'+input.code"><span v-if="index" class="combo-plus" aria-hidden="true">＋</span><span class="combo-chip" :data-input-source="input.source" :data-handheld-extended="isHandheldExtendedKey(input)">{{label(input)}}</span></template><span v-if="!visibleInputs.length" class="combo-empty">{{recording?'按住所需按键，再全部松开':'还没有录制组合'}}</span></div></div>
  <div v-if="manual" class="oem-input-picker" data-oem-picker>
   <template v-if="catalog.supported && displayCatalog.keys.length">
    <section v-for="group in [{label:'专用按键',keys:dedicatedKeys},{label:'背部按键',keys:rearKeys}].filter(group=>group.keys.length)" :key="group.label" class="oem-input-group"><strong>{{group.label}}</strong><div class="oem-input-keys"><button v-for="key in group.keys" :key="key.keyId" type="button" :data-oem-key="key.keyId" :aria-pressed="selected(key.keyId)" :disabled="busy||recordingBusy||key.captureImplemented===false" @click="emit('oem-key',key.keyId)">{{key.label}}<small v-if="key.captureImplemented===false">暂不可用</small></button></div></section>
   </template>
   <p v-else class="capture-status oem-input-empty">当前设备没有可选择的专用键或背键，请使用录制输入。</p>
   <div class="oem-input-actions"><button class="confirm-oem-input" type="button" :disabled="busy||recordingBusy||!candidate?.length" @click="emit('confirm-oem')">使用所选按键</button><button type="button" :disabled="busy||recordingBusy||!visibleInputs.length" @click="emit('clear')">清空</button><button v-if="candidate" type="button" :disabled="busy||recordingBusy" @click="emit('cancel-oem')">取消选择</button></div>
  </div>
  <div v-else class="record-actions"><button type="button" class="record-action" :class="{recording}" :disabled="busy||recordingBusy" @click="recording?emit('cancel-recording'):emit('record')">{{recording?'取消录制':inputs.length?'重新录制输入':'录制输入'}}</button><button type="button" class="clear-combination" :disabled="busy||recording||recordingBusy||!inputs.length" @click="emit('clear')">清空</button></div>
  <p v-if="mixed" class="mixed-notice" role="status">混合输入 · 含键盘：{{traditionalKeys.map(label).join(' + ')}}。可能来自掌机键盘映射，可保留使用。</p>
  <p class="capture-status" aria-live="polite">{{status || (manual ? '选择专用键或背键，无需按下实体键。' : '手柄、背键、专用键与键鼠均可录制和组合。')}}</p>
 </section>
</template>
<style scoped>
.combo-input-editor{display:grid;gap:10px;min-width:0}.combo-section-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.combo-section-head strong{font-size:14px}.combo-section-head>span,.combo-current-caption{font-size:11px;color:var(--text-dim)}.combo-current{display:grid;gap:8px;min-height:62px;padding:10px;background:var(--bg-panel);border:1px solid var(--border);border-radius:8px}.combo-current.capturing{border-color:var(--accent)}.combo-chips{display:flex;align-items:center;flex-wrap:wrap;gap:5px;min-height:26px}.combo-chip{padding:5px 8px;border-radius:6px;background:color-mix(in srgb,var(--accent) 15%,var(--bg-input));color:var(--text);font-size:12px;font-weight:600}.combo-plus,.combo-empty{color:var(--text-dim);font-size:12px}.record-actions{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px}.record-actions button{min-height:40px;border:1px solid var(--border);border-radius:7px;background:var(--bg-input);color:var(--text);padding:8px 12px;font:inherit;font-size:12px;cursor:pointer}.record-actions .record-action{background:var(--accent);color:var(--text-on-accent,#fff);border-color:var(--accent);font-weight:700}.record-actions .recording{background:var(--bg-panel);color:var(--text)}button:disabled{opacity:.45;cursor:default}.capture-status,.mixed-notice{margin:0;font-size:11px;line-height:1.5;color:var(--text-dim)}.mixed-notice{color:var(--accent)}
.input-methods{display:flex;align-items:stretch;gap:4px;min-width:0}.input-methods button{min-height:36px;padding:6px 10px;border:1px solid var(--border);border-radius:7px;background:var(--bg-input);color:var(--text-dim);font:inherit;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap}.input-methods button[aria-pressed=true]{border-color:var(--accent);color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,var(--bg-input))}.combo-section-head>span{white-space:nowrap}.oem-input-picker{display:grid;gap:9px;min-width:0}.oem-input-group{display:grid;grid-template-columns:52px minmax(0,1fr);align-items:center;gap:6px;min-width:0}.oem-input-group>strong{font-size:11px;color:var(--text-dim)}.oem-input-keys{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;max-height:150px;overflow-y:auto;padding:2px}.oem-input-keys button{display:flex;align-items:center;justify-content:center;gap:3px;flex-direction:column;min-height:38px;min-width:0;padding:6px 4px;border:1px solid var(--border);border-radius:7px;background:var(--bg-input);color:var(--text);font:inherit;font-size:12px;overflow-wrap:anywhere;cursor:pointer}.oem-input-keys button[aria-pressed=true]{color:var(--accent);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 15%,var(--bg-input))}.oem-input-keys small{font-size:9px}.oem-input-actions{display:flex;gap:6px;min-width:0}.oem-input-actions button{min-height:38px;padding:7px 9px;border:1px solid var(--border);border-radius:7px;background:var(--bg-input);color:var(--text);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}.oem-input-actions .confirm-oem-input{flex:1;border-color:var(--accent);background:var(--accent);color:var(--text-on-accent,#fff);font-weight:700}.oem-input-empty{padding:8px 0} .combo-input-editor[data-input-method=oem]{gap:7px}.combo-input-editor[data-input-method=oem] .combo-current{display:flex;align-items:center;min-height:30px;padding:6px 8px;gap:8px}.combo-input-editor[data-input-method=oem] .combo-current-caption{white-space:nowrap}.combo-input-editor[data-input-method=oem] .combo-chip{padding:4px 7px}.input-methods button:focus-visible,.oem-input-keys button:focus-visible,.oem-input-actions button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
</style>
